export const COPILOT_PLUGIN_FILES: Readonly<Record<string, string>> = {
  "com.github.copilot/hooks/agent-stop.mjs": "#!/usr/bin/env node\nimport { promises as fs } from \"node:fs\";\nimport path from \"node:path\";\nimport {\n  canonicalWorkspace,\n  isReported,\n  listCreations,\n  markReported,\n  readResponseWindow,\n  summarizeUsage\n} from \"../lib/run-log.mjs\";\n\n// Copilot `agentStop` summary: what this response created, and what it cost.\n//\n// Purely informative. The hook writes its summary to stderr, answers `{}` on\n// stdout whatever happens, and exits 0: it never blocks, never asks for a\n// continuation, never calls a model and never writes Tour content (spec #320).\n//\n// Two sources, both foreign and both tolerant: the creation journal the CodeTour\n// CLI appends to after a successful write (`<workspace>/.tours/.log/creations/`)\n// and the session transcript the Copilot CLI owns (`transcriptPath`). A Tour is\n// reported only when the attribution is established: same workspace, same\n// `sessionId` as the payload, created inside this response — the window between\n// the last `user.message` and the stop — and not in the future. A creation\n// without a session identity, or one the transcript cannot place, is never\n// guessed into the summary.\n//\n// The token reading is one per response, for the response as a whole: no Tour is\n// given a share it cannot have. `inputTokens` already includes the cache reads\n// and writes, so cache is shown as a part of the input total, never added to it;\n// an unreadable or empty window says unavailable, never zero. The\n// `<sessionId>-<responseStart>` marker keeps a second stop of the same response\n// silent.\n//\n// Silences: no payload, a hook-triggered re-entry, an unusable workspace, no\n// session identity, no response boundary, and no attributed creation. Every\n// failure is a diagnostic on stderr, never a decision.\n\nconst MAX_INPUT_BYTES = 1024 * 1024;\nconst HOOK_OUTPUT = {};\n\nfunction diagnostic(message) {\n  process.stderr.write(`CodeTour agentStop: ${message}\\n`);\n}\n\nfunction report(message) {\n  process.stderr.write(`CodeTour: ${message}\\n`);\n}\n\nconst numbers = new Intl.NumberFormat(\"en-GB\");\n\nfunction formatTokens(value) {\n  return numbers.format(value);\n}\n\n// One line for the response: input as the total that already contains the\n// cache, output beside it. A figure the session never recorded is omitted\n// rather than printed as zero.\nfunction usageLine(usage, approximate) {\n  const suffix = approximate ? \" (approximate)\" : \"\";\n  if (usage.records === 0) {\n    return `tokens unavailable (no usage records in this response)`;\n  }\n  const { sums, observed } = usage;\n  const parts = [];\n  if (observed.inputTokens) {\n    const cache = [];\n    if (observed.cacheReadTokens) cache.push(`${formatTokens(sums.cacheReadTokens)} cached reads`);\n    if (observed.cacheWriteTokens) cache.push(`${formatTokens(sums.cacheWriteTokens)} cached writes`);\n    parts.push(\n      cache.length === 0\n        ? `${formatTokens(sums.inputTokens)} in`\n        : `${formatTokens(sums.inputTokens)} in (of which ${cache.join(\", \")})`\n    );\n  }\n  if (observed.outputTokens) parts.push(`${formatTokens(sums.outputTokens)} out`);\n  if (parts.length === 0) {\n    return `tokens unavailable (no token figures in this response)`;\n  }\n  return `tokens ${parts.join(\", \")}${suffix}`;\n}\n\n// A creation can only belong to this response when it names this workspace and\n// this session identity: a record without a session, or with another agent's\n// host, is never attributed. The response window is applied afterwards.\nfunction belongsToSession(record, { workspace, sessionId }) {\n  if (record.sessionId === null || record.sessionId !== sessionId) return false;\n  if (record.host !== null && record.host !== undefined && record.host !== \"copilot\") return false;\n  return canonicalWorkspace(record.workspace) === workspace;\n}\n\nfunction attributed(record, { fromMs, untilMs }) {\n  const at = Date.parse(record.at);\n  return at >= fromMs && at <= untilMs;\n}\n\nfunction tourPathOf(record, workspace) {\n  return path.isAbsolute(record.tourPath) ? record.tourPath : path.resolve(workspace, record.tourPath);\n}\n\nasync function workspaceRealPath(cwd) {\n  if (typeof cwd !== \"string\" || !cwd) return undefined;\n  try {\n    const real = await fs.realpath(cwd);\n    const stat = await fs.stat(real);\n    return stat.isDirectory() ? canonicalWorkspace(real) : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\nasync function readInput() {\n  const chunks = [];\n  let size = 0;\n  for await (const chunk of process.stdin) {\n    size += chunk.length;\n    if (size > MAX_INPUT_BYTES) throw new Error(\"input payload is too large\");\n    chunks.push(chunk);\n  }\n  return JSON.parse(Buffer.concat(chunks).toString(\"utf8\"));\n}\n\nasync function reportResponse(input) {\n  if (!input || typeof input !== \"object\") return;\n  if (input.stop_hook_active === true || input.stopHookActive === true) return;\n  const sessionId = typeof input.sessionId === \"string\" && input.sessionId ? input.sessionId : undefined;\n  if (!sessionId) return;\n  const untilMs = Number.isFinite(input.timestamp) ? input.timestamp : Date.now();\n  const workspace = await workspaceRealPath(input.cwd);\n  if (!workspace) return;\n\n  const listed = await listCreations(workspace, untilMs);\n  // Damage in the journal is worth one diagnostic; an absent one says nothing.\n  for (const problem of listed.problems) diagnostic(`ignored creation record (${problem})`);\n  // An ordinary conversation has no candidate at all: the transcript is not\n  // read and no summary is printed.\n  const candidates = listed.records.filter(record =>\n    belongsToSession(record, { workspace, sessionId })\n  );\n  if (candidates.length === 0) return;\n\n  const window = await readResponseWindow(input.transcriptPath, untilMs);\n  if (!window.observed) {\n    diagnostic(`tokens not observed (${window.reason})`);\n    return;\n  }\n  if (await isReported(workspace, sessionId, window.fromMs)) return;\n\n  const own = candidates.filter(record => attributed(record, { fromMs: window.fromMs, untilMs }));\n  if (own.length === 0) return;\n\n  const approximate = window.approximate ? \" (approximate)\" : \"\";\n  report(`${own.length} ${own.length === 1 ? \"Tour\" : \"Tours\"} created in this response${approximate}`);\n  for (const record of own) {\n    report(`\"${record.tourTitle}\" — ${tourPathOf(record, workspace)}`);\n  }\n  report(usageLine(summarizeUsage(window.usageRecords), window.approximate));\n  if (!(await markReported(workspace, sessionId, window.fromMs))) {\n    diagnostic(\"could not mark the response as reported\");\n  }\n}\n\nasync function main() {\n  try {\n    await reportResponse(await readInput());\n  } catch (error) {\n    // A malformed payload, an unavailable workspace or any storage failure is\n    // a diagnostic; the conversation stops, untouched.\n    diagnostic(`ignored stop (${error?.message || error})`);\n  }\n  process.stdout.write(`${JSON.stringify(HOOK_OUTPUT)}\\n`);\n}\n\nawait main();\n",
  "com.github.copilot/hooks/hooks.json": "{\n  \"version\": 1,\n  \"hooks\": {\n    \"agentStop\": [\n      {\n        \"type\": \"command\",\n        \"command\": \"node \\\"${PLUGIN_ROOT}/com.github.copilot/hooks/agent-stop.mjs\\\"\",\n        \"timeoutSec\": 10\n      }\n    ]\n  }\n}\n",
  "com.github.copilot/lib/run-log.mjs": "import { createReadStream, promises as fs, realpathSync } from \"node:fs\";\nimport path from \"node:path\";\nimport { createInterface } from \"node:readline\";\n\n// Observability data for the Copilot `agentStop` hook: the creation journal the\n// CodeTour CLI writes, and the session transcript the Copilot CLI owns.\n//\n// Nothing here decides anything: the hook reports what these two files say and\n// stays silent when they say nothing. Both are foreign documents, so every\n// reader is tolerant — a missing, unreadable or malformed file yields \"not\n// observed\" instead of an error, and an unreadable record is skipped instead of\n// invalidating its neighbours.\n\n/** Creation records, relative to the workspace root (journal.ts writes them). */\nexport const CREATIONS_DIRECTORY = path.join(\".tours\", \".log\", \"creations\");\n/** The journal version this reader understands. */\nexport const CREATION_RECORD_VERSION = 1;\n/** Response markers, relative to the workspace root. */\nexport const REPORTED_DIRECTORY = path.join(CREATIONS_DIRECTORY, \".reported\");\n/** Readers ignore older creation records (spec #320). */\nexport const CREATION_RECORD_MAX_AGE_MS = 24 * 60 * 60 * 1000;\n/** Response markers are garbage after the same delay. */\nexport const REPORTED_MAX_AGE_MS = 24 * 60 * 60 * 1000;\n\n/** The token figures a Copilot session usage record carries. */\nexport const TOKEN_KEYS = [\n  \"inputTokens\",\n  \"outputTokens\",\n  \"cacheReadTokens\",\n  \"cacheWriteTokens\",\n  \"reasoningTokens\"\n];\n\n// The workspace spelling every comparison uses (ADR 0056). Node has *two*\n// realpath implementations with different answers on Windows: `realpathSync`\n// keeps an 8.3 short name while `fs.promises.realpath` answers the long on-disk\n// form. A writer using one and a reader comparing with the other never agree,\n// so both sides go through the native call, without a trailing separator.\nexport function canonicalWorkspace(value) {\n  if (typeof value !== \"string\" || value === \"\") return \"\";\n  const resolved = path.resolve(value);\n  let canonical = resolved;\n  try {\n    canonical =\n      typeof realpathSync.native === \"function\" ? realpathSync.native(resolved) : realpathSync(resolved);\n  } catch {\n    // An unavailable real path keeps the resolved argument.\n  }\n  return canonical.length > 1 && (canonical.endsWith(\"/\") || canonical.endsWith(\"\\\\\"))\n    ? canonical.slice(0, -1)\n    : canonical;\n}\n\nexport function creationsDirectory(workspace) {\n  return path.join(workspace, CREATIONS_DIRECTORY);\n}\n\nexport function reportedDirectory(workspace) {\n  return path.join(workspace, REPORTED_DIRECTORY);\n}\n\n/**\n * Whether a parsed document is one creation record of the current version.\n *\n * The identity fields are part of the contract (DESIGN §3): a creating process\n * that observes no session, response or host writes `null`, so a field that is\n * absent or of another type is a foreign record, not an anonymous creation. The\n * Pi hook keeps a copy of this rule in `packages/pi-plugin/lib/journal.mjs` and\n * the two may not disagree (`test/journal-parity.test.mjs`).\n */\nexport function isCreationRecord(value) {\n  if (!value || typeof value !== \"object\") return false;\n  const optionalString = candidate => candidate === null || typeof candidate === \"string\";\n  return (\n    value.version === CREATION_RECORD_VERSION &&\n    typeof value.workspace === \"string\" &&\n    value.workspace !== \"\" &&\n    typeof value.tourPath === \"string\" &&\n    value.tourPath !== \"\" &&\n    typeof value.tourTitle === \"string\" &&\n    typeof value.at === \"string\" &&\n    Number.isFinite(Date.parse(value.at)) &&\n    optionalString(value.sessionId) &&\n    optionalString(value.responseId) &&\n    optionalString(value.host)\n  );\n}\n\n/**\n * Every readable creation record of one workspace, oldest first. A corrupt or\n * foreign file is reported and skipped: one bad record never hides the others,\n * and an unreadable directory is an empty journal.\n */\nexport async function listCreations(workspace, now = Date.now()) {\n  const directory = creationsDirectory(workspace);\n  let names;\n  try {\n    names = await fs.readdir(directory);\n  } catch (error) {\n    return {\n      records: [],\n      problems:\n        error?.code === \"ENOENT\" ? [] : [`unreadable creation journal: ${error?.message || error}`]\n    };\n  }\n  const records = [];\n  const problems = [];\n  for (const name of names.sort()) {\n    if (!name.endsWith(\".json\") || name.startsWith(\".\")) continue;\n    const file = path.join(directory, name);\n    let parsed;\n    try {\n      parsed = JSON.parse(await fs.readFile(file, \"utf8\"));\n    } catch (error) {\n      problems.push(`${name}: ${error?.code || \"unreadable\"}`);\n      continue;\n    }\n    if (!isCreationRecord(parsed)) {\n      problems.push(`${name}: malformed`);\n      continue;\n    }\n    // An expired record can no longer be attributed and is left for pruning.\n    if (now - Date.parse(parsed.at) > CREATION_RECORD_MAX_AGE_MS) continue;\n    records.push(parsed);\n  }\n  records.sort((left, right) => Date.parse(left.at) - Date.parse(right.at));\n  return { records, problems };\n}\n\nfunction numberOrUndefined(value) {\n  return typeof value === \"number\" && Number.isFinite(value) ? value : undefined;\n}\n\n/**\n * Read one Copilot session transcript into the facts the summary needs: the\n * response boundary and the usage records it can attribute.\n *\n * The boundary is the last `user.message` at or before `untilMs`; without one\n * (a resumed or truncated transcript) the earliest event the reader can place\n * is used and the window is labelled approximate. A file that cannot be read, or that\n * carries no timestamp at all, yields no window: the hook then reports nothing\n * rather than guessing.\n */\nexport async function readResponseWindow(file, untilMs) {\n  if (typeof file !== \"string\" || file === \"\") return { observed: false, reason: \"no transcript\" };\n  const lines = createInterface({\n    input: createReadStream(file, { encoding: \"utf8\" }),\n    crlfDelay: Infinity\n  });\n  let firstAtMs = null;\n  let lastUserMessageAtMs = null;\n  const usageRecords = [];\n  try {\n    for await (const line of lines) {\n      // Cheap pre-filter: only these three event types matter.\n      if (!line.includes(\"usage_record\") && !line.includes(\"user.message\") && !line.includes(\"session.start\")) {\n        continue;\n      }\n      let event;\n      try {\n        event = JSON.parse(line);\n      } catch {\n        continue;\n      }\n      if (!event || typeof event !== \"object\") continue;\n      const atMs = typeof event.timestamp === \"string\" ? Date.parse(event.timestamp) : NaN;\n      if (!Number.isFinite(atMs)) continue;\n      if (firstAtMs === null || atMs < firstAtMs) firstAtMs = atMs;\n      if (event.type === \"user.message\") {\n        if (atMs <= untilMs && (lastUserMessageAtMs === null || atMs > lastUserMessageAtMs)) {\n          lastUserMessageAtMs = atMs;\n        }\n      } else if (event.type === \"session.usage_record\") {\n        const usage = event.data?.usage;\n        if (!usage || typeof usage !== \"object\") continue;\n        const tokens = {};\n        for (const key of TOKEN_KEYS) {\n          const value = numberOrUndefined(usage[key]);\n          if (value !== undefined) tokens[key] = value;\n        }\n        usageRecords.push({ atMs, tokens });\n      }\n    }\n  } catch (error) {\n    return { observed: false, reason: error?.code === \"ENOENT\" ? \"no transcript\" : \"unreadable transcript\" };\n  }\n  if (firstAtMs === null) return { observed: false, reason: \"no session event\" };\n  const fromMs = lastUserMessageAtMs ?? firstAtMs;\n  return {\n    observed: true,\n    fromMs,\n    approximate: lastUserMessageAtMs === null,\n    usageRecords: usageRecords.filter(record => record.atMs >= fromMs && record.atMs <= untilMs)\n  };\n}\n\n/**\n * Sum the token figures of one response. A key is observed only when at least\n * one record carried a finite number for it, so an absent figure stays absent\n * instead of becoming a zero the source never reported. `inputTokens` already\n * contains the cache reads and writes: the sums are never added together.\n */\nexport function summarizeUsage(usageRecords) {\n  const sums = {};\n  const observed = {};\n  for (const key of TOKEN_KEYS) {\n    sums[key] = 0;\n    observed[key] = false;\n  }\n  for (const record of usageRecords) {\n    for (const key of TOKEN_KEYS) {\n      const value = record.tokens[key];\n      if (value === undefined) continue;\n      sums[key] += value;\n      observed[key] = true;\n    }\n  }\n  return { records: usageRecords.length, sums, observed };\n}\n\nfunction markerName(sessionId, responseStartMs) {\n  const safe = String(sessionId).replace(/[^A-Za-z0-9._-]/g, \"_\");\n  return `${safe}-${responseStartMs}`;\n}\n\n/** Whether this response already printed its summary. */\nexport async function isReported(workspace, sessionId, responseStartMs) {\n  const file = path.join(reportedDirectory(workspace), markerName(sessionId, responseStartMs));\n  try {\n    await fs.access(file);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Mark one response as reported and drop markers that have outlived their\n * session. Returns false when the marker cannot be written; the summary is\n * already printed at that point, so the failure only costs the de-duplication.\n */\nexport async function markReported(workspace, sessionId, responseStartMs, now = Date.now()) {\n  const directory = reportedDirectory(workspace);\n  try {\n    await fs.mkdir(directory, { recursive: true });\n    await pruneReported(directory, now);\n    await fs.writeFile(\n      path.join(directory, markerName(sessionId, responseStartMs)),\n      `${new Date(responseStartMs).toISOString()}\\n`,\n      \"utf8\"\n    );\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nasync function pruneReported(directory, now) {\n  let names;\n  try {\n    names = await fs.readdir(directory);\n  } catch {\n    return;\n  }\n  for (const name of names) {\n    const file = path.join(directory, name);\n    const stat = await fs.stat(file).catch(() => undefined);\n    if (stat && now - stat.mtimeMs > REPORTED_MAX_AGE_MS) {\n      await fs.rm(file, { force: true }).catch(() => undefined);\n    }\n  }\n}\n",
  "plugin.json": "{\n  \"$schema\": \"https://agent-plugins.org/schemas/1.0.0/plugin.schema.json\",\n  \"name\": \"codetour\",\n  \"version\": \"0.1.2\",\n  \"description\": \"CodeTour: guided Tours generated with the CodeTour CLI.\",\n  \"author\": {\n    \"name\": \"CodeTour\"\n  },\n  \"homepage\": \"https://github.com/maurice30120/codetour\",\n  \"repository\": \"https://github.com/maurice30120/codetour\",\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"codetour\",\n    \"tours\",\n    \"copilot\"\n  ]\n}\n",
  "README.md": "# CodeTour Copilot plugin\n\nThis directory is the versioned **Agent Plugins 1.0** source of the CodeTour\nintegration for GitHub Copilot CLI. It is embedded in the standalone CodeTour\nCLI and installed by:\n\n```sh\ncodetour --install copilot\n```\n\n`copilot plugin install packages/copilot-plugin` installs the same directory\ndirectly (the installed CLI supports local direct installs, with a deprecation\nwarning). `copilot plugin uninstall codetour` removes it.\n\n## Contents\n\n| Path | Role |\n| --- | --- |\n| `plugin.json` | Agent Plugins 1.0 manifest (`$schema`, name, version, metadata). |\n| `skills/codetour-generate/SKILL.md` | The generation entry point: the CLI creation commands, the proposal shape and the failure handling. |\n| `com.github.copilot/hooks/hooks.json` | Copilot `agentStop` hook declaration. |\n| `com.github.copilot/hooks/agent-stop.mjs` | End-of-response summary: the created Tours and one token reading. It never blocks. |\n| `com.github.copilot/lib/run-log.mjs` | The creation-journal and session-transcript readers the hook uses. |\n| `skills/codetour-generate/references/` | The critical-review pack a `critical` Changes Tour follows: the CodeTour adaptation, the verbatim upstream skill and its MIT license. |\n\nThe plugin declares no MCP server: generation is the CLI's work, and the hook\nonly reads what the CLI wrote (ADR 0057).\n\n## Generation\n\n`/codetour-generate`, or a plain request to explain the codebase or review the\nbranch, follows\n[`skills/codetour-generate/SKILL.md`](skills/codetour-generate/SKILL.md): it\nresolves the Tour type, the review mode (Changes Tours only) and the orientation\nphrase, explores the workspace, then hands a JSON proposal to the installed CLI\nfrom the workspace root:\n\n```sh\ncodetour create-project-tour --workspace \"<absolute workspace root>\" < proposal.json\ncodetour create-changes-tour --workspace \"<absolute workspace root>\" < proposal.json\n```\n\nThe CLI validates the proposal, writes the Tour atomically and answers with one\nJSON document on standard output: `ok: true` with the absolute `tourPath`, or\n`ok: false` with `code`, `message` and the `issues` to correct. Nothing needs to\nbe installed beside the CLI and no repository checkout is involved.\n\n## The agentStop summary\n\nThe hook is purely informative. It reads two files it does not own and writes\none marker:\n\n- the **creation journal** the CLI appends to after a successful write,\n  `<workspace>/.tours/.log/creations/<createdAtMs>-<pid>-<rand>.json`, whose\n  record carries the workspace, the absolute Tour path, the title, the kind, the\n  creation time and the session identity of the creating process;\n- the **session transcript** the Copilot CLI names in the hook payload\n  (`transcriptPath`, the session's `events.jsonl`), for the response boundary\n  and the token figures.\n\nA Tour is reported only when its attribution is established: the payload\n`sessionId` matches the record's session identity (a record without one, or\nwith another agent's host, is never attributed), the canonical workspace is the\npayload `cwd`, and the record was created inside the current response —\nbetween the last `user.message` and the stop. All attributed Tours are printed\nwith their absolute path, oldest first.\n\nOne token reading follows, for the response as a whole and never per Tour:\n\n```text\nCodeTour: 2 Tours created in this response\nCodeTour: \"Flux de facturation\" — /workspace/.tours/billing.tour\nCodeTour: \"Revue critique des changements\" — /workspace/.tours/review.tour\nCodeTour: tokens 38,608 in (of which 18,818 cached reads, 19,784 cached writes), 23 out\n```\n\n- `inputTokens` already contains the cache reads and writes, so cache is shown\n  as a part of the input total and is never added to it; `reasoningTokens` is a\n  subset of the output.\n- Figures the session never recorded are omitted; a window with no usage record\n  says `tokens unavailable (…)`, never zero.\n- A fallback boundary (no `user.message` in the transcript, the resumed-session\n  case) labels the whole reading `(approximate)`.\n- One reading per response: the hook writes\n  `<workspace>/.tours/.log/creations/.reported/<sessionId>-<responseStartMs>`\n  and stays silent on a second stop of the same response.\n\nNo creation identified means no output at all. The hook always exits 0 and\nalways answers `{}`: it never blocks, never asks for a continuation and never\ncalls a model. It cannot fail a creation — a journal it cannot read is a\ndiagnostic, and an unavailable token figure only shortens the summary.\n\n## Requirements\n\n- GitHub Copilot CLI 1.0.106 or later (verified with 1.0.114). The plugin relies\n  on `${PLUGIN_ROOT}` expansion and on the `agentStop` hook payload\n  (`sessionId`, `timestamp`, `cwd`, `transcriptPath`, `stopReason`,\n  `stop_hook_active`).\n- `codetour` on `PATH`: the skill runs the installed CLI from the workspace\n  root, and no launcher is recorded in the plugin.\n- Node on `PATH` for the hook command (`node \"${PLUGIN_ROOT}/…\"`).\n- Session usage records in the transcript: without them the summary reports the\n  tokens as unavailable.\n\n### Verified limits\n\n- The hook writes to stderr, as the previous hook did. On Copilot CLI 1.0.114\n  stderr is not shown in prompt mode (`-p`) and the only honoured `agentStop`\n  output is `{}` or a block decision, which would cost a model turn; the\n  interactive TUI could not be exercised during recon. The summary is therefore\n  produced on every stop but is not proven visible in every mode.\n- `agentStop` is not guaranteed once per response (a `task_complete` stop adds\n  one); the response marker is what keeps the reading single.\n- The session events format is Copilot-internal, so every figure degrades to\n  \"unavailable\" instead of failing the stop.\n- macOS and Linux path handling uses Node APIs and has been exercised with\n  spaces in the installed plugin path and the workspace path. Windows was not\n  executed in this environment; the hook uses `exec`-free Node APIs and the\n  declaration quotes `${PLUGIN_ROOT}`, but Windows remains unverified.\n",
  "skills/codetour-generate/references/codetour-adaptation.md": "# CodeTour adaptation: critical Changes Tours\n\nThis document adapts the upstream `code-review` skill by Matt Pocock\n(reproduced verbatim in the skill pack, MIT licensed) to CodeTour Changes\nTours. It is the authoritative instruction set for every\n`create_changes_tour` call with `reviewMode: \"critical\"`. In neutral mode\n(the default) this adaptation does not apply: produce the current factual\nChanges Tour with no quality judgments.\n\n## 1. Receive the mode before analyzing\n\nThe review mode is generation data decided before any analysis. Confirm the\nmode (neutral or critical) before you inspect the diff; a mode already\nstated unambiguously in the request is never asked again, and a cancelled\nchoice stops the tour instead of generating one silently. Read the whole\nskill pack resource before writing any step: receiving the mode only in the\nfinal tool call would be too late.\n\n## 2. Analyze the same comparison the tour describes\n\nRun both review axes on the exact comparison the Changes Tour will\ndescribe: the diff from the merge-base of the base reference to the\nanalyzed head commit, plus explicitly included uncommitted changes when\nrequested. Never substitute another range. The MCP server's Git checks,\nvalidation, snapshots, and anchor verification remain the sole authority:\nwhen your analysis and the server disagree, the server wins.\n\n## 3. Standards axis — always\n\n- First search the repository for documented rules: `AGENTS.md`,\n  `CONTRIBUTING.md`, `CONTEXT.md`, documents under `docs/`, and any other\n  documented conventions (naming, structure, error handling...). A\n  documented repo rule always overrides the upstream smell baseline: where\n  a documented rule endorses what the baseline would flag, suppress the\n  smell.\n- Report each finding with the label `**Standards:**` and classify it as\n  either:\n  - a **demonstrated violation** — cite the documented rule (its file and\n    the rule itself) and quote the code that breaks it; or\n  - a **risk / code smell** — a heuristic judgement from the upstream smell\n    baseline, always presented as such, never as a violation.\n- Do not report as a new finding anything a tool already guarantees\n  (compiler and type errors, formatter and linter output, the MCP server's\n  own validation). Recycling guaranteed results adds noise, not review\n  value.\n\n## 4. Spec axis — only when a source is found\n\n- Look for a source associated with the changes, in this order:\n  1. an explicit user indication (a message, a path, or a ticket\n     reference);\n  2. issue or ticket references in the commit messages (`#123`,\n     `Closes #45`, ...);\n  3. a spec file under `docs/`, `specs/`, or `.scratch/` matching the\n     branch or feature.\n- Keep a verifiable reference to the source you used (path or ticket URL)\n  and cite the exact requirement text for each finding.\n- Report each finding with the label `**Spec:**`: requirements that are\n  missing or partial; behavior that was not asked for (scope creep);\n  requirements that look implemented but wrong.\n- Never invent requirements: every Spec finding must quote its source. If\n  the source is ambiguous, say so instead of guessing.\n- If no source is found: do not ask the user for a spec and do not block.\n  Continue with the Standards axis alone and state in the tour description\n  exactly: `Spec axis not evaluated: no spec source was found.`\n\n## 5. Integrating findings into the tour\n\n- Every step keeps a factual explanation of the change — what it does, how\n  it is implemented, and its observable effect. Review findings complement\n  the explanation; they never replace it.\n- Attach each finding inside the description of the step whose Tour Anchor\n  locates the motivating code (for a Spec finding: the implementation of\n  the requirement), with its `**Standards:**` or `**Spec:**` label and the\n  quoted rule or requirement. Do not create an extra step for every\n  suspicion: only established findings earn anchored coverage, and the\n  tour remains one coherent review path.\n- Keep the two axes separate and labeled; never merge or rerank findings\n  across axes (see the upstream \"Why two axes\").\n- Findings must anchor at lines that exist in the analyzed head commit so\n  the server's anchor validation can verify them.\n\n## 6. Honesty guarantees\n\n- Never invent defects, requirements, specs, or test results.\n- Tests you inferred from reading the change must be described as\n  inferred, never as executed; report a test as passing or failing only if\n  you observed the run.\n- Distinguish observed behavior from intended behavior.\n- If no defect is established at all, the tour remains a useful factual\n  explanation: say so plainly instead of manufacturing criticism.\n\n## 7. Sub-agents and sequential degradation\n\nPrefer the upstream structure — the two axes as parallel sub-agents, each\nwith a fresh context — when the client supports sub-agents. When it does\nnot, run the same two analyses sequentially in your own context, keeping\nthe axes separate and labeled exactly as above. The degradation changes\nonly how the work is executed, never the rules of the review.\n",
  "skills/codetour-generate/references/upstream-code-review.md": "---\nname: code-review\ndescription: \"Review the changes since a fixed point (commit, branch, tag, or merge-base) along two axes: Standards (does the code follow this repo's documented coding standards?) and Spec (does the code match what the originating issue/spec asked for?). Runs both reviews in parallel sub-agents and reports them side by side. Use when the user wants to review a branch, a PR, work-in-progress changes, or asks to \\\"review since X\\\".\"\n---\n\nTwo-axis review of the diff between `HEAD` and a fixed point the user supplies:\n\n- **Standards**: does the code conform to this repo's documented coding standards?\n- **Spec**: does the code faithfully implement the originating issue / spec?\n\nBoth axes run as **parallel sub-agents** so they don't pollute each other's context, then this skill aggregates their findings. Start every sub-agent with a fresh context window.\n\nThe issue tracker should have been provided to you. If not, tell the user to run `/setup-matt-pocock-skills`.\n\n## Process\n\n### 1. Pin the fixed point\n\nWhatever the user said is the fixed point (a commit SHA, branch name, tag, `main`, `HEAD~5`, etc.). If they didn't specify one, ask for it.\n\nCapture the diff command once: `git diff <fixed-point>...HEAD` (three-dot, so the comparison is against the merge-base). Also note the list of commits via `git log <fixed-point>..HEAD --oneline`.\n\nBefore going further, confirm the fixed point resolves (`git rev-parse <fixed-point>`) and the diff is non-empty. A bad ref or empty diff should fail here, not inside two parallel sub-agents.\n\n### 2. Identify the spec source\n\nLook for the originating spec, in this order:\n\n1. Issue references in the commit messages (`#123`, `Closes #45`, GitLab `!67`, etc.), fetched via the workflow in the tracker doc.\n2. A path the user passed as an argument.\n3. A spec file under `docs/`, `specs/`, or `.scratch/` matching the branch name or feature.\n4. If nothing is found, ask the user where the spec is. If they say there isn't one, the **Spec** sub-agent will skip and report \"no spec available\".\n\n### 3. Identify the standards sources\n\nSearch the repo for every file that documents how code should be written. When `CODING_STANDARDS.md` or `CONTRIBUTING.md` exists, it must be on the list.\n\nOn top of whatever the repo documents, the Standards axis always carries the **smell baseline** below: a fixed set of Fowler code smells (_Refactoring_, ch.3) that applies even when a repo documents nothing. Two rules bind it:\n\n- **The repo overrides.** A documented repo standard always wins; where it endorses something the baseline would flag, suppress the smell.\n- **Always a judgement call.** Each smell is a labelled heuristic (\"possible Feature Envy\"), never a hard violation. Like any standard here, skip anything tooling already enforces.\n\nEach smell reads *what it is* → *how to fix*; match it against the diff:\n\n- **Mysterious Name**: a function, variable, or type whose name doesn't reveal what it does or holds. → rename it; if no honest name comes, the design's murky.\n- **Duplicated Code**: the same logic shape appears in more than one hunk or file in the change. → extract the shared shape, call it from both.\n- **Feature Envy**: a method that reaches into another object's data more than its own. → move the method onto the data it envies.\n- **Data Clumps**: the same few fields or params keep travelling together (a type wanting to be born). → bundle them into one type, pass that.\n- **Primitive Obsession**: a primitive or string standing in for a domain concept that deserves its own type. → give the concept its own small type.\n- **Repeated Switches**: the same `switch`/`if`-cascade on the same type recurs across the change. → replace with polymorphism, or one map both sites share.\n- **Shotgun Surgery**: one logical change forces scattered edits across many files in the diff. → gather what changes together into one module.\n- **Divergent Change**: one file or module is edited for several unrelated reasons. → split so each module changes for one reason.\n- **Speculative Generality**: abstraction, parameters, or hooks added for needs the spec doesn't have. → delete it; inline back until a real need shows.\n- **Message Chains**: long `a.b().c().d()` navigation the caller shouldn't depend on. → hide the walk behind one method on the first object.\n- **Middle Man**: a class or function that mostly just delegates onward. → cut it, call the real target direct.\n- **Refused Bequest**: a subclass or implementer that ignores or overrides most of what it inherits. → drop the inheritance, use composition.\n\n### 4. Spawn both sub-agents in parallel\n\nIssue both sub-agent calls together, in the foreground, and aggregate the reports they return.\n\n**Standards sub-agent prompt** should include:\n\n- The full diff command and commit list.\n- The list of standards-source files you found in step 3, **plus the smell baseline from step 3** pasted in full (the sub-agent has no other access to it).\n- The brief: \"Report, per file/hunk where relevant, (a) every place the diff violates a documented standard: cite the standard (file + the rule); and (b) any baseline smell you spot: name it and quote the hunk. Distinguish hard violations from judgement calls: documented-standard breaches can be hard, but baseline smells are always judgement calls, and a documented repo standard overrides the baseline. Skip anything tooling enforces. Under 400 words.\"\n\n**Spec sub-agent prompt** should include:\n\n- The diff command and commit list.\n- The path or fetched contents of the spec.\n- The brief: \"Report: (a) requirements the spec asked for that are missing or partial; (b) behaviour in the diff that wasn't asked for (scope creep); (c) requirements that look implemented but where the implementation looks wrong. Quote the spec line for each finding. Under 400 words.\"\n\nIf the spec is missing, skip the Spec sub-agent and note this in the final report.\n\n### 5. Aggregate\n\nPresent the two reports under `## Standards` and `## Spec` headings, verbatim or lightly cleaned. Do **not** merge or rerank findings, because the two axes are deliberately separate (see _Why two axes_).\n\nEnd with a one-line summary: total findings per axis, and the worst issue _within each axis_ (if any). Don't pick a single winner across axes: that's the reranking the separation exists to prevent.\n\n## Why two axes\n\nA change can pass one axis and fail the other:\n\n- Code that follows every standard but implements the wrong thing → **Standards pass, Spec fail.**\n- Code that does exactly what the issue asked but breaks the project's conventions → **Spec pass, Standards fail.**\n\nReporting them separately stops one axis from masking the other.\n",
  "skills/codetour-generate/references/upstream-LICENSE.txt": "MIT License\n\nCopyright (c) 2026 Matt Pocock\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n",
  "skills/codetour-generate/SKILL.md": "---\nname: codetour-generate\ndescription: Generate a CodeTour Project Tour or Changes Tour by handing a JSON proposal to the CodeTour CLI. Use when the user asks to explain, tour or onboard onto a codebase, or to review the branch's changes, with CodeTour.\nuser-invocable: true\n---\n\n# CodeTour generation\n\nThis skill creates a real Tour file in the workspace with the `codetour` CLI.\nThe proposal travels on standard input, the CLI validates it against the\nworkspace, writes the Tour atomically, and answers with one JSON document. A\nTour is never written by hand and never replaced by prose.\n\n`codetour` on `PATH` is the documented default. When the invocation carries a\n`codetour-cli=<absolute invocation>` argument, run that value instead of\n`codetour`, with the same arguments; nothing else changes.\n\n## 1. Resolve the choices\n\nHonor what the user already said: \"review my branch critically\" means a Changes\nTour with `reviewMode: \"critical\"`, and nothing is asked twice. Ask only for\nwhat is missing, once per question, and stop without generating if the user\ncancels or declines; never silently default.\n\n- **Type** — a **Project Tour** (architecture, structure and execution paths)\n  or a **Changes Tour** (explain and review the branch's changes).\n- **Review mode** — Changes Tours only: `neutral` (factual explanation) or\n  `critical` (explanation plus review findings). Project Tours have none.\n- **Critical review method** — a `critical` Changes Tour follows the pack filed\n  in `references/` beside this file; read `references/codetour-adaptation.md`,\n  `references/upstream-code-review.md` and `references/upstream-LICENSE.txt`\n  before exploring, and keep them read while writing. Without that reading the\n  mode would only be a word. A `neutral` Changes Tour and every Project Tour\n  never open the pack.\n- **Orientation and language** — a phrase that orients the Tour (\"focus on the\n  rendering pipeline\") is optional; it also sets the language the Tour is\n  written in. Without one, write the Tour in the language of the user's request.\n\n## 2. Work in the workspace root\n\nEvery command runs at the workspace root, and `--workspace` receives that root\nas an absolute path (`git rev-parse --show-toplevel`, or the directory the user\nnamed). One creation addresses one workspace: every anchor and the Tour file\nitself stay inside it.\n\n## 3. Build the proposal\n\nOne JSON object, with the fields the CLI validates:\n\n- `title` (optional: the CLI defaults a Project Tour to `Project Overview` and\n  a Changes Tour to `Changes on <branch>`), `description`, `fileName` (a bare\n  name, written under `.tours/`), `steps` (at least one).\n- A step carries a `title`, a Markdown `description`, and optionally one anchor:\n  `file` with `line` and/or `pattern`, `directory`, `selection`\n  (`{start: {line, character}, end: {...}}`), `display: \"diff\"` with\n  `baseFile`. A step without an anchor is explanatory, which is what the\n  orientation step should be.\n- A Changes Tour also carries `reviewMode` (`neutral` or `critical`), and\n  optionally `baseRef`, `headRef` and `includeUncommittedChanges`. Read the\n  PR/MR context with `gh` or `glab` when the user gave none, and say what you\n  used; never invent a title, a goal or a finding.\n- `questions` (at most four short strings) attach the questions the reader\n  should answer at that step.\n\nExplore the workspace before proposing anything: every `file`, `line` and\n`pattern` is verified against the files on disk before a single byte is\nwritten.\n\n## 4. Hand the proposal over\n\n```sh\ncodetour create-project-tour --workspace \"<absolute workspace root>\" <<'JSON'\n{\"title\": \"…\", \"steps\": [{\"title\": \"…\", \"description\": \"…\"}]}\nJSON\n\ncodetour create-changes-tour --workspace \"<absolute workspace root>\" <<'JSON'\n{\"title\": \"…\", \"reviewMode\": \"critical\", \"steps\": [{\"title\": \"…\", \"description\": \"…\"}]}\nJSON\n```\n\n`--proposal <file>` reads the proposal from a file instead of standard input;\nboth carry the same document.\n\nExit codes say what happened:\n\n| Code | Meaning |\n| --- | --- |\n| `0` | the Tour was created; standard output holds the result document |\n| `1` | the proposal, its validation or the creation was refused |\n| `2` | usage or IO failure: missing or unknown argument, unusable workspace, unreadable proposal, explicit `--help` |\n\nStandard output carries exactly one JSON document whenever a creation is\nattempted, and a usage answer (`--help`, exit `2`) leaves it empty. Standard\nerror carries diagnostics only.\n\n## 5. Handle the result\n\nSuccess (`{\"ok\": true, …}`) reports `kind`, `title`, `tourPath` (absolute),\n`stepCount` and `warnings`. Report the title and the path to the user, and read\nthe warnings: they are readability advice, not failures.\n\nRefusal (`{\"ok\": false, \"code\": …, \"message\": …, \"issues\": [...]}`) wrote\nnothing: fix **every** `issues` entry (`path` names the field, `message` says\nwhat is wrong), then resubmit the corrected proposal. Do not retry the same\ndocument and do not lower the Tour's quality to get past a validation.\n\nExit code `2` means the command line itself was unusable (a missing\n`--workspace`, an unknown option, an unreadable proposal file). Report the\ndiagnostic; do not retry it blindly.\n\nIf `codetour` is missing, say so and stop: the generation needs the CLI on\n`PATH`, and `codetour --install copilot` reinstalls this plugin when the skill\nitself is missing. A text answer is not a Tour.\n\n## 6. Hand the Tour over to a reader\n\nNever replace the created Tour with a step list, an excerpt or a summary. Offer\nthe real readers, to run at the workspace root:\n\n- Terminal — `codetour \"<Tour title>\"`, or\n  `codetour --internal-tour \"<tour path>\"` to open the file directly;\n- VS Code — `codetour --internal-open-vscode \"<tour path>\"`, which opens the\n  Tour at its first step.\n\nA reading failure is reported with the command to run manually; it never\ninvalidates the Tour that was created.\n"
};
